issue_context.body:
Have not measured it in detail, nor investigated the assembly, but possibly a variant of this (with a new error type) _might_ shave off some cycles

```diff
diff --git a/core/vm/interpreter.go b/core/vm/interpreter.go
index 673f046a46..7609ab3be2 100644
--- a/core/vm/interpreter.go
+++ b/core/vm/interpreter.go
@@ -188,10 +188,8 @@ func (in *EVMInterpreter) Run(contract *Contract, input []byte, readOnly bool) (
 		op = contract.GetOp(pc)
 		operation := in.cfg.JumpTable[op]
 		// Validate stack
-		if sLen := stack.len(); sLen < operation.minStack {
-			return nil, &ErrStackUnderflow{stackLen: sLen, required: operation.minStack}
-		} else if sLen > operation.maxStack {
-			return nil, &ErrStackOverflow{stackLen: sLen, limit: operation.maxStack}
+		if !stack.between(operation.minStack, operation.maxStack) {
+			return nil, ErrOutOfGas
 		}
 		// Static portion of gas
 		cost = operation.constantGas // For tracing
diff --git a/core/vm/stack.go b/core/vm/stack.go
index 9e7e887ccd..e891c17a74 100644
--- a/core/vm/stack.go
+++ b/core/vm/stack.go
@@ -65,6 +65,10 @@ func (st *Stack) len() int {
 	return len(st.data)
 }
 
+func (st *Stack) between(low, high int) bool {
+	return len(st.data) > low && len(st.data) < high
+}
+
 func (st *Stack) swap(n int) {
 	st.data[st.len()-n], st.data[st.len()-1] = st.data[st.len()-1], st.data[st.len()-n]
 }
```
